<?php

declare(strict_types=1);

require_once __DIR__ . '/../bootstrap.php';
Auth::requireLogin();
$projectId = filter_var($_GET['project'] ?? null, FILTER_VALIDATE_INT);
$symbolId = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT);
