$symbol = $project === null || $symbolId === false || $symbolId === null ? null : SymbolRepository::symbol((int) $project['id'], (int) $symbolId);
if ($project === null || $symbol === null) { http_response_code(404); exit('Symbol not found.'); }
$outgoing = SymbolRepository::relationships((int) $project['id'], (int) $symbol['id']);
$incoming = SymbolRepository::relationships((int) $project['id'], (int) $symbol['id'], 'incoming');
$blast = BlastRadiusService::forSymbol((int) $project['id'], (int) $symbol['id']);
$excerpt = SourceReader::excerpt($project, (string) $symbol['path'], (int) $symbol['start_line'], (int) $symbol['end_line']);
$pageTitle = $symbol['name'];
$activePage = 'dashboard';
$activeProjectSection = 'symbols';
require __DIR__ . '/../views/header.php';
?>
<section class="app-shell v2-shell symbol-detail-page">
    <div class="breadcrumb"><a href="<?= e(url('project.php?id=' . (int) $project['id'])) ?>"><?= e($project['name']) ?></a><span>/</span><a href="<?= e(url('symbols.php?id=' . (int) $project['id'])) ?>">Symbols</a><span>/</span><span><?= e($symbol['name']) ?></span></div>
    <div class="symbol-hero"><div><div class="symbol-label-row"><span><?= e(str_replace('_', ' ', $symbol['symbol_type'])) ?></span><span class="confidence <?= e($symbol['confidence']) ?>"><?= e($symbol['confidence']) ?> confidence</span></div><h1><?= e($symbol['name']) ?></h1><code><?= e($symbol['qualified_name']) ?></code><p><?= e($symbol['path']) ?>, lines <?= (int) $symbol['start_line'] ?>-<?= (int) $symbol['end_line'] ?><?= $symbol['parent_name'] ? ', inside ' . e($symbol['parent_name']) : '' ?></p></div><div class="risk-callout <?= e($blast['risk']) ?>"><span>Edit risk</span><strong><?= e($blast['risk']) ?></strong><small>Based on confirmed and medium-confidence graph reach.</small></div></div>
    <?php require __DIR__ . '/../views/project-nav.php'; ?>
    <section class="symbol-summary-grid"><div><span>Incoming</span><strong><?= count($incoming) ?></strong><small>callers and consumers</small></div><div><span>Outgoing</span><strong><?= count($outgoing) ?></strong><small>calls and dependencies</small></div><div><span>Affected files</span><strong><?= count($blast['files']) ?></strong><small>within six hops</small></div><div><span>Routes</span><strong><?= count($blast['routes']) ?></strong><small>linked handlers</small></div><div><span>Data</span><strong><?= count($blast['tables']) ?></strong><small>tables, models, schemas</small></div></section>
    <section class="symbol-layout">
        <article class="panel source-panel"><div class="section-row"><div><h2>Source evidence</h2><p>Read-only excerpt from the private repository clone.</p></div><a href="<?= e(url('file.php?project=' . (int) $project['id'] . '&id=' . (int) $symbol['file_id'])) ?>">Open file analysis</a></div><?php if ($excerpt === null): ?><div class="empty-state-v2"><strong>Source excerpt unavailable.</strong><p>The clone moved, the file exceeded the safe limit, or the path no longer resolves inside the repository.</p></div><?php else: ?><pre class="source-excerpt" tabindex="0"><?php foreach ($excerpt['lines'] as $sourceLine): ?><span class="<?= $sourceLine['number'] >= (int) $symbol['start_line'] && $sourceLine['number'] <= (int) $symbol['end_line'] ? 'is-symbol-line' : '' ?>"><b><?= $sourceLine['number'] ?></b><code><?= e($sourceLine['text']) ?></code></span><?php endforeach; ?></pre><?php endif; ?></article>
        <aside class="panel before-edit-v2"><h2>Before you edit</h2><ol><?php foreach ($blast['checklist'] as $item): ?><li><?= e($item) ?></li><?php endforeach; ?></ol><?php if ($blast['unknowns'] !== []): ?><p class="uncertainty-note"><?= count($blast['unknowns']) ?> unresolved target<?= count($blast['unknowns']) === 1 ? '' : 's' ?> need manual verification.</p><?php endif; ?></aside>
    </section>
    <section class="relationship-columns">
