    </section>
    <section class="panel blast-panel"><div class="section-row"><div><h2>Symbol blast radius</h2><p>Direct and transitive consumers, affected routes, and data boundaries.</p></div><span class="risk-text <?= e($blast['risk']) ?>"><?= e($blast['risk']) ?> risk</span></div><div class="blast-groups"><div><h3>Direct consumers</h3><?php if ($blast['direct'] === []): ?><p>None detected.</p><?php else: ?><?php foreach ($blast['direct'] as $item): ?><a href="<?= e(url('symbol.php?project=' . (int) $project['id'] . '&id=' . (int) $item['id'])) ?>"><?= e($item['name']) ?><small><?= e($item['path']) ?>, <?= e($item['relationship']) ?></small></a><?php endforeach; ?><?php endif; ?></div><div><h3>Transitive consumers</h3><?php if ($blast['transitive'] === []): ?><p>None detected within six hops.</p><?php else: ?><?php foreach (array_slice($blast['transitive'], 0, 30) as $item): ?><a href="<?= e(url('symbol.php?project=' . (int) $project['id'] . '&id=' . (int) $item['id'])) ?>"><?= e($item['name']) ?><small><?= e($item['path']) ?>, <?= (int) $item['depth'] ?> hops</small></a><?php endforeach; ?><?php endif; ?></div><div><h3>Routes and data</h3><?php foreach ($blast['routes'] as $route): ?><a href="<?= e(url('routes.php?id=' . (int) $project['id'] . '&q=' . urlencode($route['route_path']))) ?>"><?= e($route['http_method'] . ' ' . $route['route_path']) ?><small><?= e($route['framework']) ?></small></a><?php endforeach; ?><?php foreach ($blast['tables'] as $table): ?><a href="<?= e(url('symbol.php?project=' . (int) $project['id'] . '&id=' . (int) $table['id'])) ?>"><?= e($table['name']) ?><small><?= e($table['type']) ?></small></a><?php endforeach; ?><?php if ($blast['routes'] === [] && $blast['tables'] === []): ?><p>No linked route or data boundary detected.</p><?php endif; ?></div></div></section>
